SELECT (SELECT COUNT(*) FROM d1_migrations) AS migrations, (SELECT COUNT(*) FROM d1_migrations WHERE name IN ('0000_loud_donald_blake.sql','0001_adorable_scream.sql','0002_blushing_prism.sql','0003_fancy_dreadnoughts.sql','0004_mature_makkari.sql')) AS required_prior_migrations, (SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name GLOB 'life_*') AS app_tables, (SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='life_automatic_consent') AS consent_table, (SELECT COUNT(*) FROM pragma_table_info('life_review_jobs') WHERE name='last_considered_at') AS consideration_column, (SELECT COUNT(*) FROM sqlite_master WHERE type='index' AND name='idx_life_review_job_date') AS job_date_index, (SELECT COUNT(*) FROM sqlite_master WHERE type='trigger' AND name='life_daily_reminder_intent') AS reminder_trigger, (SELECT COUNT(*) FROM sqlite_master WHERE type='view' AND name='life_daily_job_status') AS status_view;
